"""Render static assets only, never run JavaScript against scholarly websites."""
import json
from pathlib import Path
from .config import TOPICS

HTML = '''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>El almaque del Dr. Herrero | Oncología digestiva y endocrina</title><meta name="description" content="Vigilancia bibliográfica en oncología digestiva, endocrina y neuroendocrina: guías, artículos, comunicaciones y noticias científicas.">
<link rel="stylesheet" href="styles.css"></head><body><div class="layout"><header><div class="eyebrow">VIGILANCIA BIBLIOGRÁFICA · SIN IA</div><h1>El almaque del Dr. Herrero</h1><p>Oncología digestiva, endocrina y neuroendocrina · SEOM · SAOM · ESMO · ASCO · Revistas científicas</p></header>
<main><section class="visit-counter" aria-label="Visitas a la web"><div class="visit-counter-heading">VISITAS A EL ALMAQUE</div><div class="visit-counter-numbers"><div><strong id="visitas-hoy" aria-live="polite">—</strong><span>Hoy</span></div><div><strong id="visitas-total" aria-live="polite">—</strong><span>Desde que se activó el contador</span></div></div><p id="visitas-nota">Estadísticas públicas de páginas vistas · zona horaria de España peninsular</p></section><section class="metrics" id="metrics" aria-label="Contadores bibliográficos"></section><div class="toolbar"><label>Buscar <input id="search" type="search" placeholder="Título, DOI, revista, patología…"></label><label>Patología <select id="topic"><option value="">Todas</option></select></label><label>Fuente <select id="source"><option value="">Todas</option></select></label><label>Estado <select id="status"><option value="">Todos</option><option>Nueva</option><option>Actualizada</option></select></label></div><p id="statusline" role="status"></p><nav class="category-nav" id="tabs" aria-label="Categorías"></nav><div id="records"></div><div class="pagination"><button id="more" hidden>Mostrar más</button></div><section class="history"><h2>Histórico de informes</h2><p>Selecciona una ejecución para ver las novedades notificadas en esa fecha.</p><label>Informe <select id="run"><option value="">Histórico completo</option></select></label><div id="runinfo"></div></section><section class="info"><h2>Alcance y transparencia</h2><p>Este sitio muestra referencias bibliográficas públicas. No interpreta resultados, no recomienda tratamientos ni reproduce artículos completos. Los textos originales están disponibles en los enlaces a sus editores y sociedades.</p><p>Las fechas «No verificada» corresponden a enlaces de páginas oficiales que no facilitan una fecha legible automáticamente. La ausencia de novedades no garantiza ausencia de publicaciones. Las incidencias de consulta aparecen en el histórico.</p><p>Las nuevas versiones de una referencia se conservan en el registro histórico. Los cambios de URL o de metadatos pueden generar una actualización; no implican cambios de recomendaciones.</p><p>Fuentes bibliográficas: <a href="https://pubmed.ncbi.nlm.nih.gov/">PubMed / NCBI</a>. No es un servicio afiliado a NCBI, SEOM, SAOM, ESMO ni ASCO.</p><p><a href="https://www.ncbi.nlm.nih.gov/home/about/policies/">Políticas y aviso legal de NCBI</a>.</p></section></main><footer>El almaque del Dr. Herrero · Proyecto de referencia bibliográfica automatizada · <a href="https://github.com/">Código en GitHub</a></footer></div><script src="app.js" defer></script><script src="visitas-config.js" defer></script><script src="visitas.js" defer></script></body></html>'''

CSS = '''*{box-sizing:border-box}body{margin:0;background:#f4f7f9;color:#21344a;font:16px/1.6 system-ui,-apple-system,Segoe UI,sans-serif}a{color:#155d8f;overflow-wrap:anywhere}a:hover{text-decoration-thickness:2px}.layout{max-width:1100px;margin:auto;padding:0 20px}header{background:#173955;color:white;margin:0 -20px 28px;padding:36px max(20px,calc((100vw - 1100px)/2 + 20px)) 32px}header h1{font-family:Georgia,serif;font-size:clamp(29px,5vw,45px);letter-spacing:-.8px;margin:7px 0}header p{color:#cedfea;margin:0}.eyebrow{color:#a6d4df;font-size:12px;letter-spacing:2px;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px}.metric,.item,.info,.history{background:white;border:1px solid #dde6ed;border-radius:12px;padding:18px}.metric .big{font-size:29px;font-weight:750;font-variant-numeric:tabular-nums;color:#153a57}.metric .small{color:#64768a;font-size:13px}.toolbar{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:12px;margin:15px 0}label{font-size:13px;color:#51687b;font-weight:650;display:block}input,select{width:100%;background:white;color:#19364e;border:1px solid #bacddc;border-radius:8px;padding:10px;margin-top:5px;min-height:42px}.category-nav{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.category-nav button,button{border:1px solid #b9d0dc;background:white;border-radius:9px;color:#274963;padding:10px 13px;cursor:pointer;font-size:14px}.category-nav button.active{background:#173955;color:white;border-color:#173955}.item{margin:12px 0}.item h3{margin:8px 0 5px;line-height:1.35;font-size:18px}.meta{color:#63788a;font-size:13px}.chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}.chip{background:#eaf1f5;color:#34556c;padding:2px 8px;border-radius:100px;font-size:12px}.chip.new{background:#e0f4ea;color:#116b43}.chip.updated{background:#fff2d9;color:#8b560c}.item p{margin:8px 0}.item details{margin-top:8px}.item summary{cursor:pointer}.history,.info{margin-top:24px}#statusline{color:#597087;font-size:13px}.muted{color:#718394}.pagination{text-align:center;padding:10px}.history select{max-width:390px}#runinfo{margin-top:10px;font-size:14px}.issue{color:#9b4b18}.empty{padding:35px;text-align:center;color:#66798b;background:white;border:1px dashed #bbcfd9;border-radius:12px}footer{padding:34px 0;color:#6c7f91;font-size:13px}.visit-counter{background:#eaf3f8;border:1px solid #c5dce9;border-radius:12px;padding:16px 20px;margin-bottom:16px}.visit-counter-heading{font-size:12px;font-weight:800;letter-spacing:1.2px;color:#315b75}.visit-counter-numbers{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:8px}.visit-counter-numbers>div{display:flex;flex-direction:column}.visit-counter-numbers strong{font-size:clamp(24px,4vw,36px);line-height:1.2;color:#153a57;font-variant-numeric:tabular-nums}.visit-counter-numbers span{font-size:13px;color:#4d6778}.visit-counter p{color:#5b7281;font-size:12px;margin:9px 0 0}@media(max-width:720px){.metrics{grid-template-columns:repeat(2,1fr)}.toolbar{grid-template-columns:1fr 1fr}.toolbar label:first-child{grid-column:span 2}}@media(max-width:430px){.toolbar{grid-template-columns:1fr}.toolbar label:first-child{grid-column:auto}}'''

JS = r'''const $ = s => document.querySelector(s);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories = ['Guías y protocolos','Artículos científicos','Comunicaciones científicas','Noticias'];
const journalFilters = [
 {label:'NEJM', aliases:['New England Journal of Medicine','N Engl J Med','N Engl J Med (N Y)']}
];
const normSource = s => String(s||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').trim().toLowerCase();
const sourceAliases = label => journalFilters.find(x=>x.label===label)?.aliases || [label];
const sourceMatches = (actual,label) => sourceAliases(label).some(a=>normSource(a)===normSource(actual));
const sourceLabel = actual => journalFilters.find(x=>x.aliases.some(a=>normSource(a)===normSource(actual)))?.label || actual;
const configuredTopics = __CONFIGURED_TOPICS_JSON__;
const state={category:'',limit:40};let data={records:[],runs:[]};
const fmt=d=>{if(!d)return '—';const x=new Date(d);return Number.isNaN(+x)?d:x.toLocaleString('es-ES',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Madrid'})};
function runStatus(r){return r?.issues?.length ? `· ${r.issues.length} fuente(s) con incidencias` : ''}
function render(){
 const all=data.records, runs=data.runs, chosen=$('#run').value;
 const run=runs.find(x=>x.at===chosen);
 const changeMap=new Map((run?.changes||[]).map(x=>[x.key,x.status]));
 const q=$('#search').value.trim().toLowerCase(),topic=$('#topic').value,source=$('#source').value,status=$('#status').value;
 let items=all.filter(x=>(!chosen||changeMap.has(x.key))&&(!state.category||x.category===state.category)&&(!topic||x.topics.includes(topic))&&(!source||sourceMatches(x.source,source))&&(!q||[x.title,x.source,x.doi,x.pmid,...x.topics].join(' ').toLowerCase().includes(q)));
 if(status)items=items.filter(x=>(chosen?changeMap.get(x.key):(x.versions.length?'Actualizada':'Nueva'))===status);
 items.sort((a,b)=>categories.indexOf(a.category)-categories.indexOf(b.category)||b.first_seen.localeCompare(a.first_seen));
 const rcount=chosen?run.changes.length:all.length;
 const dailyCount=new Set(runs.filter(x=>x.sources_ok?.length).map(x=>new Date(x.at).toLocaleDateString('sv-SE',{timeZone:'Europe/Madrid'})).filter(x=>x>='2026-11-17'&&x<='2026-11-23')).size;
 $('#metrics').innerHTML=[['Referencias',all.length],['Actualizaciones',all.reduce((n,x)=>n+x.versions.length,0)],['Primera semana',Math.min(7,dailyCount)+'/7'],['Informes guardados',runs.length]].map(([l,n])=>`<div class="metric"><div class="big">${n}</div><div class="small">${l}</div></div>`).join('');
 $('#tabs').innerHTML=[['','Todas'],...categories.map(x=>[x,x])].map(([v,l])=>`<button class="${state.category===v?'active':''}" data-cat="${esc(v)}">${esc(l)} (${(chosen?all.filter(x=>changeMap.has(x.key)):all).filter(x=>!v||x.category===v).length})</button>`).join('');
 $('#statusline').textContent=`${items.length} referencias encontradas · Última consulta: ${runs.length?fmt(runs.at(-1).at):'pendiente'}${runStatus(runs.at(-1))}`;
 $('#records').innerHTML=items.length?items.slice(0,state.limit).map(x=>{
 const st=chosen?changeMap.get(x.key):(x.versions.length?'Actualizada':'Nueva');
 return `<article class="item"><div class="meta">${esc(x.category)} · ${esc(sourceLabel(x.source))} · Publicación: ${esc(x.date||'No verificada')}</div><h3>${esc(x.title)}</h3><div class="chips"><span class="chip ${st==='Nueva'?'new':'updated'}">${esc(st)}</span>${x.topics.map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div>${x.description?`<p class="muted">${esc(x.description)}</p>`:''}<div class="meta">Detectado: ${fmt(x.first_seen)}${x.doi?' · DOI: '+esc(x.doi):''}${x.pmid?' · PMID: '+esc(x.pmid):''}</div><p><a href="${esc(x.publisher_url||x.url)}" target="_blank" rel="noopener noreferrer">Ver publicación original</a> ${x.publisher_url?`· <a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Ficha en PubMed</a>`:''}</p>${x.versions.length?`<details><summary>Histórico de cambios registrados (${x.versions.length})</summary><ul>${x.versions.map(v=>`<li>${fmt(v.recorded_at)} — ${esc(v.title)} (${esc(v.date)})</li>`).join('')}</ul></details>`:''}</article>`}).join(''):'<div class="empty">No hay publicaciones para estos filtros. Si es la primera visita, los datos se cargarán tras la primera ejecución del programa.</div>';
 $('#more').hidden=items.length<=state.limit;
 $('#runinfo').innerHTML=run?`<p>${run.new} nuevas · ${run.updated} actualizadas · ${run.seen} referencias examinadas</p>${run.issues?.length?`<p class="issue">Incidencias: ${run.issues.map(x=>esc(x.source)).join(', ')}. Consulta el registro del proyecto para detalles.</p>`:''}`:'';
}
async function main(){try{const [r,h]=await Promise.all([fetch('records.json'),fetch('runs.json')]);if(!r.ok||!h.ok)throw Error('Faltan datos');const obj=await r.json();data.records=Object.values(obj);data.runs=await h.json();}catch(e){$('#statusline').textContent='No se han podido cargar los datos publicados.'}
const topics=[...new Set([...configuredTopics,...data.records.flatMap(x=>x.topics||[])])].sort((a,b)=>a.localeCompare(b,'es'));const knownAliases=new Set(journalFilters.flatMap(x=>x.aliases.map(normSource)));const otherSources=[...new Set(data.records.map(x=>x.source).filter(x=>!knownAliases.has(normSource(x))))].sort((a,b)=>a.localeCompare(b,'es'));
$('#topic').innerHTML+=[...topics].map(x=>`<option>${esc(x)}</option>`).join('');$('#source').innerHTML+=journalFilters.map(x=>`<option value="${esc(x.label)}">${esc(x.label)}</option>`).join('')+[...otherSources].map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
$('#run').innerHTML+=data.runs.slice().reverse().map(x=>`<option value="${esc(x.at)}">${fmt(x.at)} · ${x.new} nuevas / ${x.updated} actualizadas</option>`).join('');
['#search','#topic','#source','#status','#run'].forEach(x=>$(x).addEventListener('input',()=>{state.limit=40;render()}));
$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-cat]');if(b){state.category=b.dataset.cat;state.limit=40;render()}});
$('#more').addEventListener('click',()=>{state.limit+=40;render()});render();}main();'''


def render(site_dir='docs', db_path='data/records.json', runs_path='data/runs.json'):
    site = Path(site_dir); site.mkdir(parents=True, exist_ok=True)
    site.joinpath('index.html').write_text(HTML, encoding='utf-8')
    site.joinpath('styles.css').write_text(CSS, encoding='utf-8')
    site.joinpath('app.js').write_text(JS.replace('__CONFIGURED_TOPICS_JSON__', json.dumps(list(TOPICS), ensure_ascii=False)), encoding='utf-8')
    for source, name, empty in [(db_path, 'records.json', {}), (runs_path, 'runs.json', [])]:
        p = Path(source)
        site.joinpath(name).write_text(p.read_text(encoding='utf-8') if p.exists() else json.dumps(empty),encoding='utf-8')
    site.joinpath('.nojekyll').touch()
